const targets=$('Pack Support Targets').first().json.targets||[];
const opportunities=$input.all().map(i=>i.json||{}).filter(r=>r.Opportunity_ID&&!['Odrzucone','Zamknięte','Nieaktualne'].includes(String(r.Status||'')));
const num=v=>Number(v||0);
const now=Date.now(),soon=now+14*86400000;
const actions=[];
for(const row of targets){if(!['Szkic gotowy','Do kontaktu','Follow-up'].includes(String(row.Status||'')))continue;actions.push({kind:'SUPPORT',title:String(row.Band||row.Target_ID),score:num(row.Priority_Score)+20,owner:String(row.Owner||'do przypisania'),due:String(row.Next_Action_Date||row.Deadline||'brak'),action:String(row.Next_Action||'sprawdź i podejmij decyzję'),url:String(row.URL||row.Contact_URL||'')});}
for(const row of opportunities){const deadline=row.Deadline?new Date(String(row.Deadline).slice(0,10)+'T23:59:59').getTime():NaN;const urgent=Number.isFinite(deadline)&&deadline>=now&&deadline<=soon;const score=num(row.Relevance_Score)+(urgent?30:0)+(String(row.Priority||'')==='A'?15:0);if(score<70)continue;actions.push({kind:String(row.Category||'OKAZJA'),title:String(row.Title||row.Opportunity_ID),score,owner:String(row.Owner||'do przypisania'),due:String(row.Deadline||'brak'),action:String(row.Next_Action||'zweryfikuj i zdecyduj'),url:String(row.URL||'')});}
actions.sort((a,b)=>b.score-a.score);
const top=actions.slice(0,5);if(!top.length)return[];
const lines=top.map((x,i)=>(i+1)+'. **'+x.title+'** ['+x.kind+']\n   Owner: '+x.owner+' | termin: '+x.due+'\n   Akcja: '+x.action+(x.url?'\n   '+x.url:''));
const message='🛰️ **VIRYA — co robimy dziś?**\n\n'+lines.join('\n\n')+'\n\nKolejka: https://docs.google.com/spreadsheets/d/1aeOq_LFPp7HmFnNCenjz0RA5wIATgfd--ycbmmAGEk4/edit';
return[{json:{discord_message:message.slice(0,1950),allowed_mentions:{parse:[]}}}];
